"//! Empirical Challenger verification test harness for Phase 2 Milestone 2.
//!
//! Validates:
//! 1. Bit-exact values against `tests/empirical/test_geodetic_telemetry_dat.py` lines 350-550
//! 2. Blackbox correlation join key: `data_recorder_file_index` -> `FLY{index:03}.DAT`
//! 3. Zero heap allocation in all `fn parse(payload: &[u8])` methods via custom GlobalAlloc
//! 4. Adversarial stress-testing, boundary condition fuzzing, and edge cases

use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};

use byteorder::{ByteOrder, LittleEndian};
use flightreader_core::error::FlightReaderError;
use flightreader_core::txt::records::{
    battery::{
        celsius_to_deci_kelvin, deci_kelvin_to_celsius, raw_current_to_amperes,
        smart_battery_alerts, BatteryCellVoltages, BatteryEnergySummary, BatteryRecord,
        FlightRecordRecover, PushedBatteryRecord, SmartBatteryGoHomeStatus, SmartBatteryGroup,
        TripodStateRecord, TripodStatus, MAX_BATTERY_CELLS, RECOVER_MIN_LEN,
        SENTINEL_UNINITIALIZED, SMART_BATTERY_GROUP_MIN_LEN, TRIPOD_STATE_MIN_LEN,
        VARIANT_A_MIN_LEN, VARIANT_B_MIN_LEN,
    },
    gimbal::{
        GimbalMode, GimbalRecord, EXTENDED_PAYLOAD_LEN as GIMBAL_EXTENDED_PAYLOAD_LEN,
        MIN_PAYLOAD_LEN as GIMBAL_MIN_PAYLOAD_LEN,
    },
    home::{HomeRecord, HomeStatusFlags, MIN_HOME_PAYLOAD_LEN},
    osd::{
        BatteryType, FlightAction, FlightMode, GoHomeStatus, GroundState, ModeChannel,
        OsdFlightStatus, OsdFlyState, OsdRecord, MIN_OSD_PAYLOAD_LEN,
